from collections import deque

class Solution:
    def isTransformable(self, s: str, t: str) -> bool:
        if sorted(s) != sorted(t):
            return False
        start = tuple(map(int, s))
        goal = tuple(map(int, t))
        seen = {start}
        q = deque([start])
        while q:
            cur = q.popleft()
            if cur == goal:
                return True
            n = len(cur)
            for i in range(n):
                for j in range(i + 1, n):
                    nxt = cur[:i] + tuple(sorted(cur[i:j + 1])) + cur[j + 1:]
                    if nxt not in seen:
                        seen.add(nxt)
                        q.append(nxt)
        return False

