class Solution {
public:
    bool isTransformable(string s, string t) {
        string a = s, b = t;
        sort(a.begin(), a.end());
        sort(b.begin(), b.end());
        if (a != b) return false;
        queue<string> q;
        unordered_set<string> seen{s};
        q.push(s);
        while (!q.empty()) {
            string cur = q.front(); q.pop();
            if (cur == t) return true;
            int n = cur.size();
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++) {
                    string nxt = cur;
                    sort(nxt.begin() + i, nxt.begin() + j + 1);
                    if (seen.insert(nxt).second) q.push(nxt);
                }
        }
        return false;
    }
};

