import java.util.*;

class Solution {
    public boolean isTransformable(String s, String t) {
        char[] a = s.toCharArray(), b = t.toCharArray();
        Arrays.sort(a);
        Arrays.sort(b);
        if (!Arrays.equals(a, b)) return false;
        Queue<String> q = new LinkedList<>(List.of(s));
        Set<String> seen = new HashSet<>(List.of(s));
        while (!q.isEmpty()) {
            String cur = q.poll();
            if (cur.equals(t)) return true;
            int n = cur.length();
            for (int i = 0; i < n; i++)
                for (int j = i + 1; j < n; j++) {
                    char[] arr = cur.toCharArray();
                    Arrays.sort(arr, i, j + 1);
                    String nxt = new String(arr);
                    if (seen.add(nxt)) q.add(nxt);
                }
        }
        return false;
    }
}

