var isTransformable = function(s, t) {
    if ([...s].sort().join('') !== [...t].sort().join('')) return false;
    const seen = new Set([s]);
    const q = [s];
    while (q.length) {
        const cur = q.shift();
        if (cur === t) return true;
        const n = cur.length;
        for (let i = 0; i < n; i++)
            for (let j = i + 1; j < n; j++) {
                const nxt = cur.slice(0, i)
                    + [...cur.slice(i, j + 1)].sort().join('')
                    + cur.slice(j + 1);
                if (!seen.has(nxt)) {
                    seen.add(nxt);
                    q.push(nxt);
                }
            }
    }
    return false;
};

