        pos = [[] for _ in range(10)]
        for i, ch in enumerate(s):
            pos[int(ch)].append(i)
        head = [0] * 10
        for ch in t:
            d = int(ch)
            if head[d] >= len(pos[d]):
                return False
            i = pos[d][head[d]]
            for e in range(d):
                if head[e] < len(pos[e]) and pos[e][head[e]] < i:
                    return False
            head[d] += 1
        return True

