class Solution {
public:
    bool isTransformable(string s, string t) {
        vector<vector<int>> pos(10);
        for (int i = 0; i < (int)s.size(); i++)
            pos[s[i] - '0'].push_back(i);
        vector<int> head(10, 0);
        for (char ch : t) {
            int d = ch - '0';
            if (head[d] >= (int)pos[d].size()) return false;
            int i = pos[d][head[d]];
            for (int e = 0; e < d; e++)
                if (head[e] < (int)pos[e].size() && pos[e][head[e]] < i) return false;
            head[d]++;
        }
        return true;
    }
};

