class Solution {
    public boolean isTransformable(String s, String t) {
        List<List<Integer>> pos = new ArrayList<>();
        for (int i = 0; i < 10; i++) pos.add(new ArrayList<>());
        for (int i = 0; i < s.length(); i++)
            pos.get(s.charAt(i) - '0').add(i);
        int[] head = new int[10];
        for (int k = 0; k < t.length(); k++) {
            int d = t.charAt(k) - '0';
            if (head[d] >= pos.get(d).size()) return false;
            int i = pos.get(d).get(head[d]);
            for (int e = 0; e < d; e++)
                if (head[e] < pos.get(e).size() && pos.get(e).get(head[e]) < i) return false;
            head[d]++;
        }
        return true;
    }
}

